#include <stdio.h>

/* teste do desafio o-diario-crescente — counter_protocol (03-tdd 3.9.3).
   Canal retorno: nenhuma captura de stdout. Cada cenario prepara o caderno
   ANTES da chamada (remove + fopen "w"), para que o fopen de leitura nunca
   devolva NULL. O cenario 1 prova a ACUMULACAO (duas rodadas, seis linhas)
   e o cenario 2 prova que a rodada nao apaga o que ja estava no caderno —
   as duas coisas reprovam o modo "w". */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int oDiarioCrescente(int dia);

SM_TEST(duas_rodadas_seis_linhas) {
    FILE *semente = fopen("diario.txt", "w");
    fclose(semente);

    checa_int("a rodada do dia 1 devolve 1", oDiarioCrescente(1), 1,
              "com o caderno aberto, gravar as tres linhas da certo");
    checa_int("a rodada do dia 2 devolve 1", oDiarioCrescente(2), 1,
              "a segunda rodada abre o mesmo caderno e grava de novo");

    FILE *f = fopen("diario.txt", "r");
    char linha[80] = "(nada gravado)";
    fgets(linha, 80, f);
    checa_str("linha 1", linha, "dia 1: acordei\n",
              "as linhas do dia 1 continuam no caderno depois da segunda rodada");
    fgets(linha, 80, f);
    checa_str("linha 2", linha, "dia 1: estudei C\n",
              "a ordem das linhas e a ordem em que foram gravadas");
    fgets(linha, 80, f);
    checa_str("linha 3", linha, "dia 1: dormi\n",
              "o dia 1 fecha na terceira linha");
    fgets(linha, 80, f);
    checa_str("linha 4", linha, "dia 2: acordei\n",
              "a segunda rodada comeca onde a primeira parou: no fim do caderno");
    fgets(linha, 80, f);
    checa_str("linha 5", linha, "dia 2: estudei C\n",
              "o dia 2 traz as mesmas tres linhas, com o numero do parametro");
    fgets(linha, 80, f);
    checa_str("linha 6", linha, "dia 2: dormi\n",
              "o caderno acumulado tem seis linhas, tres de cada rodada");
    char fim[80] = "(nada gravado)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada gravado)",
              "duas rodadas de tres linhas dao seis: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(a_rodada_nao_apaga_o_que_ja_havia) {
    FILE *semente = fopen("diario.txt", "w");
    fprintf(semente, "anotacao antiga\n");
    fclose(semente);

    oDiarioCrescente(5);

    FILE *f = fopen("diario.txt", "r");
    char linha[80] = "(nada gravado)";
    fgets(linha, 80, f);
    checa_str("a anotacao antiga continua no lugar", linha, "anotacao antiga\n",
              "o modo que acrescenta nao zera o caderno ao abrir");
    fgets(linha, 80, f);
    checa_str("o registro novo vem depois dela", linha, "dia 5: acordei\n",
              "a escrita vai para o fim: o que ja estava la fica na frente");
    fclose(f);
}

