#include <stdio.h>

int oDiarioCrescente(int dia) {
    FILE *f = fopen("diario.txt", "a");
    if (f == NULL) {
        return 0;
    }
    fprintf(f, "dia %d: acordei\n", dia);
    fprintf(f, "dia %d: estudei C\n", dia);
    fprintf(f, "dia %d: dormi\n", dia);
    fclose(f);
    return 1;
}
